]

# Notice the values paired at same distances from center
# Center of 5x5 is (2,2)

from collections import defaultdict

# For each value, count how many times it appears
counts = defaultdict(list)
for r in range(5):
    for c in range(5):
        v = grid[r][c]
        if v != 9:
            counts[v].append((r, c))

print("Value occurrences:")
for v, positions in sorted(counts.items()):
    print(f"  {v}: {positions} (count={len(positions)})")

# Maybe form continuous paths?
# Let's see what happens if we fill diagonals or connect symmetrically

# Check distances from center (2,2)
center = (2, 2)
def dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

pos_by_dist = defaultdict(list)
for r in range(5):
    for c in range(5):
        if grid[r][c] != 9:
            d = dist((r,c), center)
            pos_by_dist[d].append((r, c, grid[r][c]))

print("\nPositions by Manhattan distance from center:")
for d in sorted(pos_by_dist.keys()):
    print(f"  Distance {d}: {pos_by_dist[d]}")

