# And the symmetric one
sym_fill = [[9]*5 for _ in range(5)]
idx = 0
for r in range(5):
    for c in range(5):
        if idx < len(non_9s):
            # Place at (r,c) and symmetric position
            sym_fill[r][c] = non_9s[idx]
            if (r, c) != (4-r, 4-c):
                sym_fill[4-r][4-c] = non_9s[idx]
