                v_first = result[r][0] if result[r][0] != 9 else row[0]
                v_last = result[r][4] if result[r][4] != 9 else row[4]
                # If we know one end's value, fill opposite with it
                if v_first != 9 and c == 4 or v_last != 9 and c == 0:
                    if v_first != 9:
                        result[r][c] = v_first
                    elif v_last != 9:
                        result[r][c] = v_last
                # For inner 9s: maybe fill with something else?
                elif c > 0 and c < 4:
                    # Fill with average or mode?
                    # Try most common in row (excluding 9)
                    vals = [row[i] for i in range(5) if row[i] != 9]
                    if vals:
                        from collections import Counter
                        most = Counter(vals).most_common(1)[0][0]
                        result[r][c] = most

